'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) copy[key] = clone(value[key]);
    return copy;
  }
  return value;
}

function validateProfile(profile) {
  if (!isPlainObject(profile) || typeof profile.id !== 'string' || profile.id.length === 0) {
    throw new TypeError('profile must have a nonempty string id');
  }
}

function createProfileRepository(initialProfiles) {
  if (!Array.isArray(initialProfiles)) throw new TypeError('initialProfiles must be an array');

  const records = new Map();
  for (const profile of initialProfiles) {
    validateProfile(profile);
    if (records.has(profile.id)) throw new TypeError('profile ids must be unique');
    records.set(profile.id, clone(profile));
  }

  return {
    get(id) {
      if (typeof id !== 'string') throw new TypeError('id must be a string');
      return records.has(id) ? clone(records.get(id)) : null;
    },
    replace(id, profile) {
      if (typeof id !== 'string') throw new TypeError('id must be a string');
      validateProfile(profile);
      if (profile.id !== id) throw new TypeError('profile id must match id');
      if (!records.has(id)) throw new RangeError('unknown profile id');
      records.set(id, profile);
      return clone(records.get(id));
    },
    list() {
      return Array.from(records.values(), clone);
    }
  };
}

module.exports = { createProfileRepository };

