'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createProfileRepository']);
const { createProfileRepository } = api;

const shared = { flags: ['a'] };
const initial = [
  { id: 'one', name: 'First', data: shared },
  { id: 'two', name: 'Second', data: shared }
];
const repo = createProfileRepository(initial);
initial[0].name = 'mutated';
shared.flags.push('input-change');
initial.push({ id: 'three' });

assert.deepStrictEqual(repo.list(), [
  { id: 'one', name: 'First', data: { flags: ['a'] } },
  { id: 'two', name: 'Second', data: { flags: ['a'] } }
]);
assert.equal(repo.get('missing'), null);
const first = repo.get('one');
const firstAgain = repo.get('one');
assert.notStrictEqual(first, firstAgain);
assert.notStrictEqual(first.data, firstAgain.data);
first.data.flags.push('returned-change');
first.name = 'changed';
assert.deepStrictEqual(repo.get('one'), {
  id: 'one', name: 'First', data: { flags: ['a'] }
});

const listing = repo.list();
assert.notStrictEqual(listing[0], listing[1]);
assert.notStrictEqual(listing[0].data, listing[1].data);
listing[0].data.flags.push('list-change');
assert.deepStrictEqual(repo.get('two').data.flags, ['a']);

const replacement = { id: 'one', name: 'Replacement', nested: { score: 7 } };
const replaced = repo.replace('one', replacement);
assert.deepStrictEqual(replaced, replacement);
assert.notStrictEqual(replaced, replacement);
assert.notStrictEqual(replaced.nested, replacement.nested);
replacement.nested.score = 99;
replaced.nested.score = 42;
assert.equal(repo.get('one').nested.score, 7);
assert.deepStrictEqual(repo.list().map((profile) => profile.id), ['one', 'two']);

assert.deepStrictEqual(createProfileRepository([]).list(), []);
for (const invalid of [null, {}, 'profiles']) {
  assert.throws(() => createProfileRepository(invalid), TypeError);
}
for (const profiles of [
  [null], [[]], [{ id: '' }], [{ id: 12 }],
  [{ id: 'x' }, { id: 'x' }]
]) {
  assert.throws(() => createProfileRepository(profiles), TypeError);
}
assert.throws(() => repo.replace(7, { id: 'one' }), TypeError);
assert.throws(() => repo.replace('one', null), TypeError);
assert.throws(() => repo.replace('one', { id: 'two' }), TypeError);
assert.throws(() => repo.replace('unknown', { id: 'unknown' }), RangeError);

